# -*- coding: utf-8 -*-\n\"\"\"\nValidador de Estrutura do Plugin GeoServiço-CLIPPER\nVerifica se todos os arquivos e configurações estão corretos\n\"\"\"\n\nimport os\nimport sys\nfrom pathlib import Path\n\n\nclass PluginValidator:\n    \"\"\"Validador de estrutura e configuração do plugin\"\"\"\n    \n    def __init__(self, plugin_dir):\n        self.plugin_dir = plugin_dir\n        self.errors = []\n        self.warnings = []\n        self.info = []\n    \n    def validate_all(self):\n        \"\"\"Executar todas as validações\"\"\"\n        print(\"=\"*60)\n        print(\"GeoServiço-CLIPPER - Validador de Plugin\")\n        print(\"=\"*60)\n        print()\n        \n        self.validate_structure()\n        self.validate_metadata()\n        self.validate_python_files()\n        self.validate_icon()\n        self.validate_documentation()\n        \n        self.print_results()\n    \n    def validate_structure(self):\n        \"\"\"Validar estrutura de diretórios e arquivos obrigatórios\"\"\"\n        print(\"[1/5] Validando estrutura de arquivos...\")\n        \n        required_files = [\n            'metadata.txt',\n            '__init__.py',\n            'geosservico_clipper.py',\n            'dialog.py',\n            'earth_engine_handler.py',\n            'utils.py'\n        ]\n        \n        for filename in required_files:\n            filepath = os.path.join(self.plugin_dir, filename)\n            if os.path.exists(filepath):\n                self.info.append(f\"✓ Arquivo obrigatório encontrado: {filename}\")\n            else:\n                self.errors.append(f\"✗ Arquivo obrigatório não encontrado: {filename}\")\n        \n        optional_files = [\n            'processing_provider.py',\n            'test_plugin.py',\n            'icon.png',\n            'README.md',\n            'INSTALL.md',\n            'EXAMPLES.md',\n            'requirements.txt'\n        ]\n        \n        for filename in optional_files:\n            filepath = os.path.join(self.plugin_dir, filename)\n            if os.path.exists(filepath):\n                self.info.append(f\"✓ Arquivo opcional encontrado: {filename}\")\n            else:\n                self.warnings.append(f\"⚠ Arquivo opcional não encontrado: {filename}\")\n    \n    def validate_metadata(self):\n        \"\"\"Validar arquivo metadata.txt\"\"\"\n        print(\"[2/5] Validando metadata.txt...\")\n        \n        metadata_path = os.path.join(self.plugin_dir, 'metadata.txt')\n        \n        if not os.path.exists(metadata_path):\n            self.errors.append(\"✗ Arquivo metadata.txt não encontrado\")\n            return\n        \n        required_fields = [\n            'name',\n            'qgisMinimumVersion',\n            'version',\n            'author',\n            'email',\n            'description'\n        ]\n        \n        with open(metadata_path, 'r', encoding='utf-8') as f:\n            content = f.read()\n        \n        for field in required_fields:\n            if field + '=' in content:\n                self.info.append(f\"✓ Campo obrigatório encontrado: {field}\")\n            else:\n                self.errors.append(f\"✗ Campo obrigatório não encontrado: {field}\")\n        \n        # Validações específicas\n        if 'qgisMinimumVersion=3.40' in content:\n            self.info.append(\"✓ Versão mínima do QGIS correta (3.40)\")\n        else:\n            self.warnings.append(\"⚠ Versão mínima do QGIS pode estar incorreta\")\n        \n        if 'GeoServiço-CLIPPER' in content:\n            self.info.append(\"✓ Nome do plugin correto\")\n        else:\n            self.errors.append(\"✗ Nome do plugin incorreto\")\n    \n    def validate_python_files(self):\n        \"\"\"Validar arquivos Python\"\"\"\n        print(\"[3/5] Validando arquivos Python...\")\n        \n        # Validar __init__.py\n        init_path = os.path.join(self.plugin_dir, '__init__.py')\n        if os.path.exists(init_path):\n            with open(init_path, 'r', encoding='utf-8') as f:\n                content = f.read()\n            \n            if 'def classFactory' in content:\n                self.info.append(\"✓ Função classFactory encontrada em __init__.py\")\n            else:\n                self.errors.append(\"✗ Função classFactory não encontrada em __init__.py\")\n        \n        # Validar geosservico_clipper.py\n        main_path = os.path.join(self.plugin_dir, 'geosservico_clipper.py')\n        if os.path.exists(main_path):\n            with open(main_path, 'r', encoding='utf-8') as f:\n                content = f.read()\n            \n            if 'class GeoServicio_Clipper' in content:\n                self.info.append(\"✓ Classe principal encontrada em geosservico_clipper.py\")\n            else:\n                self.errors.append(\"✗ Classe principal não encontrada em geosservico_clipper.py\")\n        \n        # Validar dialog.py\n        dialog_path = os.path.join(self.plugin_dir, 'dialog.py')\n        if os.path.exists(dialog_path):\n            with open(dialog_path, 'r', encoding='utf-8') as f:\n                content = f.read()\n            \n            if 'class GeoServicioClipperDialog' in content:\n                self.info.append(\"✓ Classe de diálogo encontrada em dialog.py\")\n            else:\n                self.errors.append(\"✗ Classe de diálogo não encontrada em dialog.py\")\n        \n        # Validar earth_engine_handler.py\n        ee_path = os.path.join(self.plugin_dir, 'earth_engine_handler.py')\n        if os.path.exists(ee_path):\n            with open(ee_path, 'r', encoding='utf-8') as f:\n                content = f.read()\n            \n            if 'class EarthEngineHandler' in content:\n                self.info.append(\"✓ Classe EarthEngineHandler encontrada\")\n            else:\n                self.errors.append(\"✗ Classe EarthEngineHandler não encontrada\")\n            \n            if 'def clip_mapbiomas' in content:\n                self.info.append(\"✓ Método clip_mapbiomas encontrado\")\n            else:\n                self.errors.append(\"✗ Método clip_mapbiomas não encontrado\")\n    \n    def validate_icon(self):\n        \"\"\"Validar ícone do plugin\"\"\"\n        print(\"[4/5] Validando ícone...\")\n        \n        icon_path = os.path.join(self.plugin_dir, 'icon.png')\n        \n        if os.path.exists(icon_path):\n            size = os.path.getsize(icon_path)\n            if size > 0:\n                self.info.append(f\"✓ Ícone encontrado ({size} bytes)\")\n            else:\n                self.errors.append(\"✗ Arquivo de ícone vazio\")\n        else:\n            self.warnings.append(\"⚠ Ícone não encontrado (icon.png)\")\n    \n    def validate_documentation(self):\n        \"\"\"Validar documentação\"\"\"\n        print(\"[5/5] Validando documentação...\")\n        \n        doc_files = {\n            'README.md': 'Documentação principal',\n            'INSTALL.md': 'Guia de instalação',\n            'EXAMPLES.md': 'Exemplos de uso'\n        }\n        \n        for filename, description in doc_files.items():\n            filepath = os.path.join(self.plugin_dir, filename)\n            if os.path.exists(filepath):\n                size = os.path.getsize(filepath)\n                self.info.append(f\"✓ {description} encontrado ({filename}, {size} bytes)\")\n            else:\n                self.warnings.append(f\"⚠ {description} não encontrado ({filename})\")\n    \n    def print_results(self):\n        \"\"\"Exibir resultados da validação\"\"\"\n        print()\n        print(\"=\"*60)\n        print(\"RESULTADOS DA VALIDAÇÃO\")\n        print(\"=\"*60)\n        print()\n        \n        if self.errors:\n            print(\"❌ ERROS:\")\n            for error in self.errors:\n                print(f\"  {error}\")\n            print()\n        \n        if self.warnings:\n            print(\"⚠️  AVISOS:\")\n            for warning in self.warnings:\n                print(f\"  {warning}\")\n            print()\n        \n        if self.info:\n            print(\"✅ INFORMAÇÕES:\")\n            for info in self.info:\n                print(f\"  {info}\")\n            print()\n        \n        print(\"=\"*60)\n        print(\"RESUMO\")\n        print(\"=\"*60)\n        print(f\"Erros: {len(self.errors)}\")\n        print(f\"Avisos: {len(self.warnings)}\")\n        print(f\"Informações: {len(self.info)}\")\n        print()\n        \n        if len(self.errors) == 0:\n            print(\"✅ Plugin validado com sucesso!\")\n            return True\n        else:\n            print(\"❌ Plugin contém erros que precisam ser corrigidos!\")\n            return False\n\n\ndef main():\n    \"\"\"Função principal\"\"\"\n    plugin_dir = os.path.dirname(os.path.abspath(__file__))\n    validator = PluginValidator(plugin_dir)\n    success = validator.validate_all()\n    sys.exit(0 if success else 1)\n\n\nif __name__ == '__main__':\n    main()\n
